	/** 
	 * jumpstart the process by instantiating2 Supplier
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		supplierId = SupplierService.getSupplierInstance()
		.createSupplier( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		SupplierService.getSupplierInstance()
				.createSupplier( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.supplierSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Supplier : " + successValue.getSupplierId());
							  if (successValue.getSupplierId().equals(supplierId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfSupplierList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Supplier test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on supplier consumed")
					);
			subscriber.supplierSubscribe( supplierId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Supplier : " + successValue.getSupplierId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfSupplierList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on supplier for supplierId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Supplier. 
	 */
	protected Supplier read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Supplier" );

		Supplier entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Supplier with primary key" );
		msg.append( supplierId );
		
		SupplierFetchOneSummary fetchOneSummary = new SupplierFetchOneSummary( supplierId );

		try {
			entity = SupplierService.getSupplierInstance().getSupplier( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Supplier " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Supplier.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Supplier." );

		StringBuilder msg = new StringBuilder( "Failed to update a Supplier : " );        
		Supplier entity = read();
		UpdateSupplierCommand command = generateUpdateCommand();
		command.setSupplierId(entity.getSupplierId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Supplier." );

			// for use later on...
			supplierId = entity.getSupplierId();

			SupplierService proxy = SupplierService.getSupplierInstance();  

			proxy.updateSupplier( command ).get();

			LOGGER.info( "-- Successfully saved Supplier - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + supplierId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Supplier.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Supplier." );

		Supplier entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Supplier with id " + supplierId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Supplier with id " + supplierId );

			throw e;
		}

		try{
			SupplierService.getSupplierInstance().delete( new DeleteSupplierCommand( entity.getSupplierId() ) ).get();
			LOGGER.info( "-- Successfully deleted Supplier with id " + supplierId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Supplier with id " + supplierId );

			throw e;
		}
	}

	/**
	 * get all Suppliers.
	 */
	protected List<Supplier> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Suppliers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Supplier : " );        
		List<Supplier> collection  = new ArrayList<>();

		try {
			// call the static get method on the SupplierService
			collection = SupplierService.getSupplierInstance().getAllSupplier();
			assertNotNull( collection, "An Empty collection of Supplier was incorrectly returned.");
			
			// Now print out the values
			Supplier entity = null;            
			Iterator<Supplier> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getSupplierId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

